        String mostPopularColor = getMostPopularColor(colorCounts);
        int mostPopularCount = colorCounts.get(mostPopularColor);

        System.out.println("Most popular car color: " + mostPopularColor);
        System.out.println("Count: " + mostPopularCount);
    }

    /**
     * Counts the occurrences of each car color in the given list.
     *
     * @param cars the list of cars
     * @return a map where keys are car colors and values are their respective counts
     */
    public static Map<String, Integer> countCarColors(List<Car> cars) {
        Map<String, Integer> colorCounts = new HashMap<>();
        for (Car car : cars) {
            String color = car.getColor();
            colorCounts.put(color, colorCounts.getOrDefault(color, 0) + 1);
        }
        return colorCounts;
    }

    /**
     * Finds the most popular car color from the given map.
     *
     * @param colorCounts the map of car colors and their counts
     * @return the most popular car color
     */
    public static String getMostPopularColor(Map<String, Integer> colorCounts) {
        return Collections.max(colorCounts.entrySet(), Comparator.comparingInt(Map.Entry::getValue)).getKey();
    }
}
```

### Explanation

1.  The `Car` class represents a car with a `color` attribute.
2.  The `countCarColors` method takes a list of `Car` objects and returns a map where keys are car colors and values are their respective counts.
3.  The `getMostPopularColor` method finds the most popular car color from the given map by using the `Collections.max` method with a comparator that compares the values (counts) of the map entries.
4.  In the `main` method, we create a list of `Car` objects, count their colors, find the most popular color, and print the result.

